package com.aoo.bcg.common.room;
import com.aoo.bcg.gamespi.time.AuthoritativeTimeSource;import java.security.SecureRandom;import java.time.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class RoomCodePolicyTest{@Test void issuesNormalizedUnambiguousCollisionReservedCodes(){var time=new AuthoritativeTimeSource(Clock.fixed(Instant.parse("2026-08-23T00:00:00Z"),ZoneOffset.UTC));var policy=new RoomCodePolicy(new SecureRandom(new byte[]{1,2,3}),new InMemoryRoomCodeStore(),time,Duration.ofHours(2),Duration.ofHours(24));String code=policy.issue();assertEquals(8,code.length());assertEquals(code,policy.normalize(" "+code.toLowerCase()+" "));assertTrue(policy.active(code));assertThrows(IllegalArgumentException.class,()->policy.normalize("00000000"));}}
